import { afterNextRender, Component, DOCUMENT, inject, signal } from '@angular/core';

type BorderKind = 'radius' | 'width' | 'style';

interface BorderToken {
  name: string;
  value: string;
  className?: string;
}

interface BorderSection {
  title: string;
  kind: BorderKind;
  tokens: BorderToken[];
}

