      background: #fff;
      padding: 0.6rem 0.75rem;
      font: inherit;
      cursor: pointer;
    }
    .bar-row:hover {
      border-color: #cfcfcf;
    }
    .bar-row__name {
      font-size: 0.78rem;
    }
    .bar-row__value {
      font-size: 0.72rem;
