      border-radius: 4px;
      background: #0a7d34;
    }
    .grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
      gap: 0.6rem;
    }
    .card {
      display: flex;
      flex-direction: column;
      gap: 0.5rem;
      position: relative;
      text-align: left;
      border: 1px solid #ececec;
      border-radius: 10px;
      background: #fff;
      padding: 0.75rem;
      font: inherit;
      cursor: pointer;
    }
    .card:hover {
      border-color: #cfcfcf;
    }
    .card--value {
      flex-direction: row;
      align-items: baseline;
      justify-content: space-between;
      gap: 0.75rem;
    }
    .meta {
      display: flex;
      flex-direction: column;
      min-width: 0;
    }
    .meta__name {
      font-size: 0.78rem;
    }
